def extract_databases(resp):
  data=resp.get('data',resp)
  out=[]
  for db in data.get('results',[]):
    title=''.join(t.get('plain_text','') for t in (db.get('title') or [])).strip() or '(untitled)'
    out.append({'title':title,'id':db.get('id'),'archived':db.get('archived',False)})
  return sorted(out,key=lambda x:x['title'].lower())
